import React from 'react';
import { 
  TrendingUp, 
  CheckCircle, 
  XCircle, 
  AlertCircle, 
  Target,
  BookOpen,
  Lightbulb
} from 'lucide-react';

const Results = ({ results }) => {
  const {
    match_score,
    matched_skills,
    missing_skills,
    resume_skills,
    jd_skills,
    suggestions
  } = results;

  const getScoreColor = (score) => {
    if (score >= 80) return 'text-success-600';
    if (score >= 60) return 'text-warning-600';
    return 'text-danger-600';
  };

  const getScoreBgColor = (score) => {
    if (score >= 80) return 'bg-success-100';
    if (score >= 60) return 'bg-warning-100';
    return 'bg-danger-100';
  };

  const getScoreMessage = (score) => {
    if (score >= 80) return 'Excellent Match!';
    if (score >= 60) return 'Good Match';
    if (score >= 40) return 'Moderate Match';
    return 'Low Match';
  };

  const getScoreIcon = (score) => {
    if (score >= 60) return <CheckCircle className="w-6 h-6" />;
    return <AlertCircle className="w-6 h-6" />;
  };

  return (
    <div className="space-y-6 animate-fade-in">
      {/* Match Score Card */}
      <div className={`card ${getScoreBgColor(match_score)} border-2`}>
        <div className="text-center">
          <div className={`inline-flex items-center justify-center w-16 h-16 rounded-full ${getScoreBgColor(match_score)} mb-4`}>
            <div className={getScoreColor(match_score)}>
              {getScoreIcon(match_score)}
            </div>
          </div>

          <h2 className="text-3xl font-bold mb-2">
            <span className={getScoreColor(match_score)}>{match_score}%</span>
          </h2>

          <p className={`text-lg font-medium ${getScoreColor(match_score)}`}>
            {getScoreMessage(match_score)}
          </p>

          <div className="mt-4">
            <div className="w-full bg-gray-200 rounded-full h-3">
              <div 
                className={`h-3 rounded-full transition-all duration-1000 ease-out ${
                  match_score >= 80 ? 'bg-success-500' :
                  match_score >= 60 ? 'bg-warning-500' : 'bg-danger-500'
                }`}
                style={{ width: `${Math.min(match_score, 100)}%` }}
              />
            </div>
          </div>
        </div>
      </div>

      {/* Skills Analysis */}
      <div className="grid md:grid-cols-2 gap-6">
        {/* Matched Skills */}
        <div className="card">
          <h3 className="text-lg font-semibold mb-4 flex items-center text-success-700">
            <CheckCircle className="w-5 h-5 mr-2" />
            Matched Skills ({matched_skills.length})
          </h3>

          {matched_skills.length > 0 ? (
            <div className="flex flex-wrap gap-2">
              {matched_skills.map((skill, index) => (
                <span key={index} className="skill-matched">
                  {skill}
                </span>
              ))}
            </div>
          ) : (
            <p className="text-gray-500 italic">No matched skills found</p>
          )}
        </div>

        {/* Missing Skills */}
        <div className="card">
          <h3 className="text-lg font-semibold mb-4 flex items-center text-warning-700">
            <XCircle className="w-5 h-5 mr-2" />
            Missing Skills ({missing_skills.length})
          </h3>

          {missing_skills.length > 0 ? (
            <div className="flex flex-wrap gap-2">
              {missing_skills.map((skill, index) => (
                <span key={index} className="skill-missing">
                  {skill}
                </span>
              ))}
            </div>
          ) : (
            <p className="text-gray-500 italic">All required skills found!</p>
          )}
        </div>
      </div>

      {/* Detailed Skills Breakdown */}
      <div className="grid md:grid-cols-2 gap-6">
        {/* Resume Skills */}
        <div className="card">
          <h3 className="text-lg font-semibold mb-4 flex items-center text-primary-700">
            <BookOpen className="w-5 h-5 mr-2" />
            Your Skills ({resume_skills.length})
          </h3>

          {resume_skills.length > 0 ? (
            <div className="flex flex-wrap gap-2 max-h-40 overflow-y-auto">
              {resume_skills.map((skill, index) => (
                <span key={index} className="skill-neutral">
                  {skill}
                </span>
              ))}
            </div>
          ) : (
            <p className="text-gray-500 italic">No skills detected</p>
          )}
        </div>

        {/* Job Requirements */}
        <div className="card">
          <h3 className="text-lg font-semibold mb-4 flex items-center text-primary-700">
            <Target className="w-5 h-5 mr-2" />
            Required Skills ({jd_skills.length})
          </h3>

          {jd_skills.length > 0 ? (
            <div className="flex flex-wrap gap-2 max-h-40 overflow-y-auto">
              {jd_skills.map((skill, index) => (
                <span key={index} className="skill-neutral">
                  {skill}
                </span>
              ))}
            </div>
          ) : (
            <p className="text-gray-500 italic">No skills detected in job description</p>
          )}
        </div>
      </div>

      {/* Suggestions */}
      {suggestions && suggestions.length > 0 && (
        <div className="card border-l-4 border-primary-500">
          <h3 className="text-lg font-semibold mb-4 flex items-center text-primary-700">
            <Lightbulb className="w-5 h-5 mr-2" />
            Suggestions to Improve Your Resume
          </h3>

          <ul className="space-y-3">
            {suggestions.map((suggestion, index) => (
              <li key={index} className="flex items-start">
                <div className="w-2 h-2 bg-primary-500 rounded-full mt-2 mr-3 flex-shrink-0" />
                <span className="text-gray-700">{suggestion}</span>
              </li>
            ))}
          </ul>
        </div>
      )}

      {/* Score Breakdown */}
      <div className="card bg-gray-50">
        <h3 className="text-lg font-semibold mb-4">Score Breakdown</h3>

        <div className="space-y-3">
          <div className="flex justify-between items-center">
            <span className="text-gray-600">Skills Match</span>
            <span className="font-medium">
              {jd_skills.length > 0 
                ? Math.round((matched_skills.length / jd_skills.length) * 100) 
                : 0}%
            </span>
          </div>

          <div className="flex justify-between items-center">
            <span className="text-gray-600">Semantic Similarity</span>
            <span className="font-medium">{match_score}%</span>
          </div>

          <div className="flex justify-between items-center">
            <span className="text-gray-600">Skills Coverage</span>
            <span className="font-medium">
              {matched_skills.length} / {jd_skills.length} skills
            </span>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Results;
